-- RentNest sample data: import AFTER rentnest_mysql.sql.
-- For a fresh database with no accounts, listings, or other application records.
-- Import once. Do not import after running npm run seed.
-- All demo accounts use password 12345678 (stored as Argon2id hashes).
-- Sessions and reset tokens are created by real login/recovery actions.
USE rentnest_import;
SET NAMES utf8mb4;
START TRANSACTION;

