INSERT INTO `messages` (`id`, `conversation_id`, `sender_id`, `message_text`, `sent_at`, `delivered_at`, `read_at`) VALUES (1, 1, 1, 'Assalamu alaikum. Is the apartment in Gulshan, Dhaka available for a viewing?', '2026-10-01 10:00:00', '2026-10-01 10:01:00', '2026-10-01 10:05:00');
INSERT INTO `messages` (`id`, `conversation_id`, `sender_id`, `message_text`, `sent_at`, `delivered_at`, `read_at`) VALUES (2, 1, 16, 'Wa alaikum assalam. Yes, you can visit on Friday afternoon.', '2026-10-01 11:00:00', '2026-10-01 11:01:00', '2026-10-01 11:05:00');
INSERT INTO `messages` (`id`, `conversation_id`, `sender_id`, `message_text`, `sent_at`, `delivered_at`, `read_at`) VALUES (3, 1, 1, 'Thank you. Are the service charges included in the monthly rent?', '2026-10-01 12:00:00', '2026-10-01 12:01:00', NULL);
INSERT INTO `messages` (`id`, `conversation_id`, `sender_id`, `message_text`, `sent_at`, `delivered_at`, `read_at`) VALUES (4, 1, 16, 'Water and security are included. Electricity is billed separately.', '2026-10-01 13:00:00', '2026-10-01 13:01:00', NULL);
